using PKHeX.Core;
using PokeRNGKit.SaveEditor;
internal static class Trainer9EditingTests
{
    internal static void Run()
    {
        foreach(var version in new[]{GameVersion.SL,GameVersion.VL})foreach(int revision in new[]{0,1,2})
        {
            var original=SvBlockFixtureTests.Create(version,revision);var save=new SAV9SV(original.ToArray());save.EnrollmentDate.Timestamp=new DateTime(2020,1,2);save.LastSaved.Timestamp=new DateTime(2020,1,3,4,5,6);var before=save.Write().ToArray();var catalog=Trainer9Editing.Read(save,Br4Editing.Hash(before));Check(catalog.Revision==revision&&catalog.Version==version.ToString()&&(catalog.Blueberry is not null)==(revision>=2),"Real revision/version gate");Check(catalog.Images.Length==3,"All source images");Check(save.Write().Span.SequenceEqual(before),"Read preserves all encrypted bytes");Check(catalog.Map.Quaternion.Length==4,"All quaternion components preserved");Console.WriteLine($"PASS initial Trainer9 {version}/{revision}: source read/revision/map metadata/three image positions and full original; edit/source image fixtures pending");
            var request=new Trainer9Request(Br4Editing.Hash(before),"TRAINER",0xFFFFFFFF,1,2,version.ToString(),"9999999","9999999",revision>=2?"7654321":"0","65535","99","99","1932-01-01T00:00:00","4095-12-31T23:59:59",true,["123.456789","-12.345678","0.000001","360.000000"],revision>=2?uint.MaxValue:null,revision>=2?uint.MaxValue:null,revision>=2?1:null,[]);
            var actual=new SAV9SV(before.ToArray());Trainer9Actions.Apply(actual,request);var oracle=new SAV9SV(before.ToArray());oracle.Version=version;oracle.Gender=1;oracle.ID32=uint.MaxValue;oracle.Money=9999999;oracle.LeaguePoints=9999999;oracle.Language=2;oracle.OT="TRAINER";oracle.PlayedHours=65535;oracle.PlayedMinutes=39;oracle.PlayedSeconds=39;oracle.EnrollmentDate.Timestamp=new DateTime(1932,1,1);oracle.LastSaved.Timestamp=new DateTime(4095,12,31,23,59,59);oracle.SetCoordinates(123.456789f,-12.345678f,0.000001f);oracle.SetPlayerRotation(0,(float)Math.Sin(Math.PI),0,(float)Math.Cos(Math.PI));if(revision>=2){oracle.BlueberryPoints=7654321;oracle.BlueberryQuestRecord.QuestsDoneSolo=uint.MaxValue;oracle.BlueberryQuestRecord.QuestsDoneGroup=uint.MaxValue;oracle.ThrowStyle=ThrowStyle9.OriginalStyle;}
            Check(actual.Write().Span.SequenceEqual(oracle.Write().Span),"Independent full-file source save and map quaternion oracle");Check(before.AsSpan().SequenceEqual(save.Write().Span),"Original unchanged after clone edit");
            foreach(string operation in new[]{"clothing","bike","stakes","tm","fly"}.Concat(revision>=2?new[]{"throwStyles","coaches","legendaries"}:[]))
            {
                var changed=new SAV9SV(before.ToArray());var expected=new SAV9SV(before.ToArray());switch(operation){case "clothing":PlayerFashionUnlock9.UnlockBase(expected.Accessor,expected.Gender);break;case "bike":foreach(string block in new[]{"FSYS_RIDE_DASH_ENABLE","FSYS_RIDE_SWIM_ENABLE","FSYS_RIDE_HIJUMP_ENABLE","FSYS_RIDE_GLIDE_ENABLE","FSYS_RIDE_CLIMB_ENABLE"})expected.Accessor.GetBlock(block).ChangeBooleanType(SCTypeCode.Bool2);if(expected.Accessor.TryGetBlock("FSYS_RIDE_FLIGHT_ENABLE",out var flight))flight.ChangeBooleanType(SCTypeCode.Bool2);break;case "stakes":expected.CollectAllStakes();break;case "tm":expected.UnlockAllTMRecipes();break;case "fly":foreach(uint block in Trainer9Fly.Keys)if(expected.Accessor.TryGetBlock(block,out var fly))fly.ChangeBooleanType(SCTypeCode.Bool2);break;case "throwStyles":expected.UnlockAllThrowStyles();break;case "coaches":expected.UnlockAllCoaches();break;case "legendaries":expected.ActivateSnacksworthLegendaries();break;}
                Trainer9Actions.Apply(changed,request with{Operations=[operation]});Trainer9Actions.Apply(expected,request);Check(changed.Write().Span.SequenceEqual(expected.Write().Span),"Source command-before-save/current gender full-file oracle");
            }
            var unchanged=new SAV9SV(before.ToArray());var unchangedRequest=request with{MapUpdated=false,Map=["invalid"]};Trainer9Actions.Apply(unchanged,unchangedRequest);Check(unchanged.RX==save.RX&&unchanged.RY==save.RY&&unchanged.RZ==save.RZ&&unchanged.RW==save.RW,"Unchanged map ignores text and preserves quaternion");
            Console.WriteLine($"PASS Trainer9 source save {version}/{revision}: all scalars/time modulo/dates/UInt32 Blueberry, independent encrypted complete bytes, MapUpdated/quaternion and original");
            foreach(string tid in new[]{"","0","999999","967295"})foreach(string sid in new[]{"","0","4293","4294","9999"})
            {
                var actualId=new PK9{ID32=0xFFFFFFFF};var expectedId=new PK9{ID32=0xFFFFFFFF};Trainer9Ids.Apply(actualId,[new(tid,sid)]);uint s=sid.Length==0?0:uint.Parse(sid);if(s>4294){s=4294;if(!expectedId.IsValidTrainerID7(s,expectedId.GetTrainerTID7()))s=4293;}else if(!expectedId.IsValidTrainerID7(s,expectedId.GetTrainerTID7()))s=4293;expectedId.SetTrainerSID7(s);uint t=tid.Length==0?0:uint.Parse(tid);if(t>999999)t=999999;else if(t==999999&&expectedId.IsValidTrainerID7(sid7:t,expectedId.GetTrainerTID7()))t=999998;expectedId.SetTrainerTID7(t);Check(actualId.ID32==expectedId.ID32,"Source SID-first/TID event normalization across empty/UInt32 boundaries");
            }
            foreach(var trash in new Hall6Trash[]{new("prepare"),new("clear"),new("text",Text:"RAW"),new("hex",Hex:catalog.NameTrash)})
            {
                var altered=new SAV9SV(before.ToArray());var expectedTrash=new SAV9SV(before.ToArray());Trainer7Editing.Trash(expectedTrash,expectedTrash.MyStatus.OriginalTrainerTrash,expectedTrash.OT,v=>expectedTrash.OT=v,trash);Trainer9Actions.Apply(altered,request with{NameEvents=[trash]});Trainer9Actions.Apply(expectedTrash,request with{NameEvents=[]});Check(altered.Write().Span.SequenceEqual(expectedTrash.Write().Span),"Source trash event before final-save/name-no-overwrite full-file parity");
            }
            var imageSave=new SAV9SV(before.ToArray());foreach(var keys in new[]{(SaveBlockAccessor9SV.KPictureProfileCurrent,SaveBlockAccessor9SV.KPictureProfileCurrentWidth,SaveBlockAccessor9SV.KPictureProfileCurrentHeight),(SaveBlockAccessor9SV.KPictureIconCurrent,SaveBlockAccessor9SV.KPictureIconCurrentWidth,SaveBlockAccessor9SV.KPictureIconCurrentHeight),(SaveBlockAccessor9SV.KPictureIconInitial,SaveBlockAccessor9SV.KPictureIconInitialWidth,SaveBlockAccessor9SV.KPictureIconInitialHeight)})
            {
                imageSave.Blocks.SetBlockValue(keys.Item2,4u);imageSave.Blocks.SetBlockValue(keys.Item3,4u);var raw=imageSave.Blocks.GetBlock(keys.Item1).Data;raw[..8].Clear();System.Buffers.Binary.BinaryPrimitives.WriteUInt16LittleEndian(raw,0xF800);System.Buffers.Binary.BinaryPrimitives.WriteUInt16LittleEndian(raw[2..],0x07E0);System.Buffers.Binary.BinaryPrimitives.WriteUInt32LittleEndian(raw[4..],0xE4E4E4E4);
            }
            var imageBytes=imageSave.Write().ToArray();var images=Trainer9Editing.Read(imageSave,Br4Editing.Hash(imageBytes)).Images;Check(images.All(i=>i.Available&&i.Width==4&&i.Height==4&&Convert.FromBase64String(i.Pixels!).Length==64),"Three actual DXT1 image positions renderable");var expectedPixels=DXT1.Decompress(imageSave.Blocks.GetBlock(SaveBlockAccessor9SV.KPictureProfileCurrent).Data,4,4);for(int i=0;i<expectedPixels.Length;i+=4)(expectedPixels[i],expectedPixels[i+2])=(expectedPixels[i+2],expectedPixels[i]);Check(Convert.FromBase64String(images[0].Pixels!).AsSpan().SequenceEqual(expectedPixels),"Independent Core BGRA/RGBA exact pixels");Check(imageSave.Write().Span.SequenceEqual(imageBytes),"Image decoding preserves complete bytes");imageSave.Blocks.SetBlockValue(SaveBlockAccessor9SV.KPictureProfileCurrentWidth,3u);Check(!Trainer9Editing.Read(imageSave,"").Images[0].Available,"Nonmultiple image size rejected without allocation");
        }
    }
    private static void Check(bool value,string message){if(!value)throw new Exception(message);}
}
